   434  njs_int_t
   435  njs_lexer_next_token(njs_lexer_t *lexer, njs_lexer_token_t *token)
   436  {
   437      u_char  c, *p;
   438
   439      c = ' ';
   440
   441      while (lexer->start < lexer->end) {
   442          c = *lexer->start++;
   443
   444          if (njs_tokens[c] != NJS_TOKEN_SPACE) {
   445              break;
   446          }
   447      }
   448
   449      lexer->keyword = 0;
   450      token->type = njs_tokens[c];
   451
   452      switch (token->type) {
   453
   454      case NJS_TOKEN_LETTER:
   455          return njs_lexer_word(lexer, token);
   456
   457      case NJS_TOKEN_DOUBLE_QUOTE:
   458      case NJS_TOKEN_SINGLE_QUOTE:
   459          njs_lexer_string(lexer, token, c);
   460          break;
   461
   462      case NJS_TOKEN_DOT:
   463          p = lexer->start;
   464
   465          if (p + 1 < lexer->end
   466              && njs_tokens[p[0]] == NJS_TOKEN_DOT
   467              && njs_tokens[p[1]] == NJS_TOKEN_DOT)
   468          {
   469              token->text.start = lexer->start - 1;
   470              token->text.length = (p - token->text.start) + 2;
   471
   472              token->type = NJS_TOKEN_ELLIPSIS;
   473
   474              lexer->start += 2;
   475
   476              return NJS_OK;
   477          }
   478
   479          if (p == lexer->end || njs_tokens[*p] != NJS_TOKEN_DIGIT) {
   480              token->text.start = lexer->start - 1;
   481              token->text.length = p - token->text.start;
   482
   483              token->type = NJS_TOKEN_DOT;
   484
   485              return NJS_OK;
   486          }
   487
   488          /* Fall through. */
   489
   490      case NJS_TOKEN_DIGIT:
   491          njs_lexer_number(lexer, token);
   492          break;
   493
   494      case NJS_TOKEN_DIVISION:
   495          njs_lexer_division(lexer, token);
   496          break;
   497
   498      case NJS_TOKEN_ASSIGNMENT:
   499          njs_lexer_multi(lexer, token, njs_assignment_token,
   500                          njs_nitems(njs_assignment_token));
   501          break;
   502
   503      case NJS_TOKEN_ADDITION:
   504          njs_lexer_multi(lexer, token, njs_addition_token,
   505                          njs_nitems(njs_addition_token));
   506          break;
   507
   508      case NJS_TOKEN_SUBSTRACTION:
   509          njs_lexer_multi(lexer, token, njs_substraction_token,
   510                          njs_nitems(njs_substraction_token));
   511          break;
   512
   513      case NJS_TOKEN_MULTIPLICATION:
   514          njs_lexer_multi(lexer, token, njs_multiplication_token,
   515                          njs_nitems(njs_multiplication_token));
   516          break;
   517
   518      case NJS_TOKEN_REMAINDER:
   519          njs_lexer_multi(lexer, token, njs_remainder_token,
   520                          njs_nitems(njs_remainder_token));
   521          break;
   522
   523      case NJS_TOKEN_BITWISE_AND:
   524          njs_lexer_multi(lexer, token, njs_bitwise_and_token,
   525                          njs_nitems(njs_bitwise_and_token));
   526          break;
   527
   528      case NJS_TOKEN_BITWISE_XOR:
   529          njs_lexer_multi(lexer, token, njs_bitwise_xor_token,
   530                          njs_nitems(njs_bitwise_xor_token));
   531          break;
   532
   533      case NJS_TOKEN_BITWISE_OR:
   534          njs_lexer_multi(lexer, token, njs_bitwise_or_token,
   535                          njs_nitems(njs_bitwise_or_token));
   536          break;
   537
   538      case NJS_TOKEN_LOGICAL_NOT:
   539          njs_lexer_multi(lexer, token, njs_logical_not_token,
   540                          njs_nitems(njs_logical_not_token));
   850
   851  illegal_token:
   852
   853      token->text.length = p - token->text.start;
   854
   855      token->type = NJS_TOKEN_ILLEGAL;
   856  }
