   859  static void
   860  njs_lexer_multi(njs_lexer_t *lexer, njs_lexer_token_t *token,
   861      const njs_lexer_multi_t *multi, size_t length)
   862  {
   863      u_char  c;
   864
   865      token->text.start = lexer->start - 1;
   866
   867      while (length != 0 && multi != NULL) {
   868          c = lexer->start[0];
   869
   870          if (c == multi->symbol) {
   871              lexer->start++;
   872
   873              token->type = multi->token;
   874
   875              if (multi->count == 0) {
   876                  break;
   877              }
   878
   879              length = multi->count;
   880              multi = multi->next;
   881
   882          } else {
   883              length--;
   884              multi++;
   885          }
   886      }
   887
   888      token->text.length = lexer->start - token->text.start;
   889  }
